59	// Surcharges are applied as (amount * percent) / 100 rather than via a decimal
60	// multiplier (e.g. * 1.1): the integer intermediate is exact, whereas 100 * 1.1
61	// is 110.00000000000001 in binary floating point. Since the final amount feeds
62	// straight into Math.ceil, that error would round a 115 G premium up to 116 G.
63	const percentOf = (amount: number, percent: number): number =>
64	  (amount * percent) / 100;
65	
66	const addPercent = (amount: number, percent: number): number =>
67	  amount + percentOf(amount, percent);
68	
69	const itemBasePremium = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
70	
71	const BLOCK_SIZE = 3;
72	const BLOCK_BASE_PREMIUM = 60;
73	
74	const sumItemBasePremiums = (items: Item[]): number =>
75	  items.reduce((sum, item) => sum + itemBasePremium(item), 0);
76	
77	/** Items of one and the same type, e.g. the three runes that form a block. */
78	type TypeGroup = Item[];
79	
80	const groupByType = (items: Item[]): TypeGroup[] => [
81	  ...items
82	    .reduce(
83	      (groups, item) =>
84	        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
85	      new Map<string, TypeGroup>(),
86	    )
87	    .values(),
88	];
89	
90	const formsBlock = (group: TypeGroup): boolean => group.length === BLOCK_SIZE;
91	
92	const groupBasePremium = (group: TypeGroup): number =>
93	  formsBlock(group) ? BLOCK_BASE_PREMIUM : sumItemBasePremiums(group);
94	
95	const policyBasePremium = (items: Item[]): number =>
96	  groupByType(items).reduce((sum, group) => sum + groupBasePremium(group), 0);
