107	/**
108	 * Item-scoped modifiers apply to the affected item's own base premium, not to
109	 * the policy total.
110	 */
111	const ITEM_SURCHARGE_RULES: ItemSurchargeRule[] = [
112	  { applies: (item) => item.cursed === true, percent: CURSE_PERCENT },
113	  {
114	    applies: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
115	    percent: HIGH_ENCHANTMENT_PERCENT,
116	  },
117	];
118	
119	const totalSurchargePercent = (item: Item): number =>
120	  ITEM_SURCHARGE_RULES.reduce(
121	    (percent, rule) => (rule.applies(item) ? percent + rule.percent : percent),
122	    0,
123	  );
