125	const itemSurcharge = (item: Item): number =>
126	  percentOf(itemBasePremium(item), totalSurchargePercent(item));
127	
128	const totalItemSurcharges = (items: Item[]): number =>
129	  items.reduce((sum, item) => sum + itemSurcharge(item), 0);
130	
131	const LOYALTY_PERCENT = 20;
132	const LOYALTY_THRESHOLD_YEARS = 2;
133	
134	/**
135	 * Policy-scoped modifiers apply to the policy base premium (the sum of all
136	 * item base premiums), independently of any item-scoped surcharges.
137	 */
138	const policyModifierPercent = (customer: Customer): number =>
139	  FIRST_INSURANCE_PERCENT -
140	  (customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS ? LOYALTY_PERCENT : 0);
