const LOYALTY_DISCOUNT_PERCENT = -20;
const LOYALTY_THRESHOLD_YEARS = 2;

/**
 * Everything a policy-scoped rule may depend on: the customer, plus where this
 * quote sits in the scenario (which is what the follow-up-contract discount
 * keys off).
 */
interface Policy {
  customer: Customer;
  precedingQuoteCount: number;
}

/**
 * Policy-scoped modifiers apply to the policy base premium (the sum of all
 * item base premiums), independently of any item-scoped surcharges.
 */
const POLICY_MODIFIER_RULES: ModifierRule<Policy>[] = [
  { applies: () => true, percent: FIRST_INSURANCE_PERCENT },
  {
    applies: ({ customer }) =>
      customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS,
    percent: LOYALTY_DISCOUNT_PERCENT,
  },
];

const quotePremium = (step: QuoteStep, policy: Policy): number => {
  const basePremium = policyBasePremium(step.items);
  return Math.ceil(
    basePremium +
      percentOf(basePremium, applicablePercent(POLICY_MODIFIER_RULES, policy)) +
      totalItemSurcharges(step.items) +
      PROCESSING_FEE,
  );
};

const runStep = (step: Step, policy: Policy): StepResult => {
  if (step.op === "quote") return { premium: quotePremium(step, policy) };
  throw new Error(`Unsupported step: ${step.op}`);
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map((step, index) =>
    runStep(step, {
      customer: scenario.customer,
      precedingQuoteCount: scenario.steps
        .slice(0, index)
        .filter((earlier) => earlier.op === "quote").length,
    }),
  ),
});

